function getRiskColor(data: CountyData | undefined): string {
  if (!data || data.total === 0) return '#e2e8f0'; // slate-200
  const highPct = data.HIGH / data.total;
  const medPct = data.MEDIUM / data.total;
  if (highPct >= 0.3) return '#fca5a5';   // red-300
  if (highPct >= 0.15) return '#fecaca';   // red-200
  if (medPct >= 0.4) return '#fde68a';     // amber-200
  if (medPct >= 0.2) return '#fef3c7';     // amber-100
  return '#bbf7d0';                         // green-200
}

function getRiskBorder(data: CountyData | undefined): string {
  if (!data || data.total === 0) return '#94a3b8'; // slate-400
  const highPct = data.HIGH / data.total;
  if (highPct >= 0.3) return '#dc2626';   // red-600
  if (highPct >= 0.15) return '#ef4444';   // red-500
  return '#64748b';                         // slate-500
}

export function KenyaHotspotMap() {
  const refetchInterval = useRefetchInterval();
  const [hovered, setHovered] = useState<string | null>(null);
  const [tooltipPos, setTooltipPos] = useState({ x: 0, y: 0 });

  const { data, isLoading } = useQuery({
    queryKey: ['analytics', 'geographic-heatmap'],
    queryFn: () => analyticsApi.getGeographicHeatmap(),
    refetchInterval,
    staleTime: 2 * 60 * 1000,
  });

  const counties = (data as HeatmapResponse)?.counties ?? {};

  const summaryLine = useMemo(() => {
    const entries = Object.entries(counties)
      .filter(([name]) => name.toLowerCase() !== 'unknown')
      .map(([name, d]) => ({ name, high: (d as CountyData).HIGH || 0, total: (d as CountyData).total || 0 }))
      .sort((a, b) => b.high - a.high);

    if (entries.length === 0) return null;

    const totalHigh = entries.reduce((s, e) => s + e.high, 0);
    const top2 = entries.slice(0, 2);
    const top2High = top2.reduce((s, e) => s + e.high, 0);
    const pct = totalHigh > 0 ? Math.round((top2High / totalHigh) * 100) : 0;

    return `${top2.map(e => e.name).join(' and ')} are the most active hotspots with ${pct}% of all high-risk reports.`;
  }, [counties]);

  if (isLoading) {
    return <div className="animate-pulse h-64 rounded-xl bg-slate-100" />;
  }

  const hoveredData = hovered ? counties[hovered] as CountyData | undefined : undefined;

  return (
    <div className="relative">
      <svg
        viewBox="0 0 500 600"
        className="w-full max-w-md mx-auto"
        style={{ maxHeight: 500 }}
      >
        {Object.entries(COUNTY_PATHS).map(([name, { d }]) => {
          const cd = counties[name] as CountyData | undefined;
          return (
            <path
              key={name}
              d={d}
              fill={getRiskColor(cd)}
              stroke={hovered === name ? '#1e293b' : getRiskBorder(cd)}
              strokeWidth={hovered === name ? 2 : 0.8}
              className="cursor-pointer transition-colors duration-150"
              onMouseEnter={(e) => {
                setHovered(name);
                const rect = (e.target as SVGElement).ownerSVGElement?.getBoundingClientRect();
                if (rect) {
                  setTooltipPos({
                    x: e.clientX - rect.left,
                    y: e.clientY - rect.top - 10,
                  });
                }
              }}
              onMouseMove={(e) => {
                const rect = (e.target as SVGElement).ownerSVGElement?.getBoundingClientRect();
                if (rect) {
                  setTooltipPos({
                    x: e.clientX - rect.left,
                    y: e.clientY - rect.top - 10,
                  });
                }
              }}
              onMouseLeave={() => setHovered(null)}
            />
          );
        })}
      </svg>

      {/* Tooltip */}
      {hovered && (
        <div
          className="absolute pointer-events-none z-10 bg-slate-900 text-white text-xs rounded-lg px-3 py-2 shadow-lg"
          style={{
            left: tooltipPos.x,
            top: tooltipPos.y,
            transform: 'translate(-50%, -100%)',
          }}
        >
          <p className="font-semibold">{hovered}</p>
          {hoveredData ? (
            <p>
              {hoveredData.total} reports —{' '}
              <span className="text-red-300">{hoveredData.HIGH} HIGH</span>,{' '}
              <span className="text-amber-300">{hoveredData.MEDIUM} MED</span>,{' '}
              <span className="text-green-300">{hoveredData.LOW} LOW</span>
            </p>
          ) : (
            <p className="text-slate-400">No reports</p>
          )}
        </div>
      )}

      {/* Legend */}
      <div className="flex items-center justify-center gap-4 mt-3 text-xs text-slate-600">
        <span className="flex items-center gap-1"><span className="w-3 h-3 rounded bg-red-300 inline-block" /> High risk</span>
        <span className="flex items-center gap-1"><span className="w-3 h-3 rounded bg-amber-200 inline-block" /> Medium</span>
        <span className="flex items-center gap-1"><span className="w-3 h-3 rounded bg-green-200 inline-block" /> Low</span>
        <span className="flex items-center gap-1"><span className="w-3 h-3 rounded bg-slate-200 inline-block" /> No data</span>
      </div>

      {/* Summary line */}
      {summaryLine && (
        <p className="text-sm text-slate-600 text-center mt-2">{summaryLine}</p>
      )}
    </div>
  );
}
